export const dimensions = [
  ['Can the system be understood?', 'Evaluate explanations for faithfulness and usefulness; communicate capabilities and limits.'],
  ['Who experiences the errors?', 'Compare relevant groups and outcomes, including people who are poorly represented in the data.'],
  ['What happens when conditions change?', 'Test failures, distribution shift and adversarial conditions; plan safe responses.'],
  ['How are data protected?', 'Examine collection, access, provenance and appropriate use throughout the data lifecycle.'],
  ['Who is responsible?', 'Define ownership, document decisions and provide ways to question or challenge outcomes.'],
  ['Can a person intervene?', 'Give people meaningful control, suitable information and a workable path to override or escalate.'],
  ['What are the wider effects?', 'Consider resource use, accessibility and consequences for communities and the environment.']
];
